package com.northstarbank.console.web;import com.northstarbank.console.integration.TierClient;import com.northstarbank.console.service.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.io.IOException;import java.math.BigDecimal;import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@Controller @RequestMapping("/customers") public class CustomerController{private final CustomerService customers;private final com.northstarbank.console.security.AuthorizationService auth;private final TierClient tiers;private final FileStorageService files;private final FinancialService financial;public CustomerController(CustomerService c,com.northstarbank.console.security.AuthorizationService a,TierClient t,FileStorageService f,FinancialService x){customers=c;auth=a;tiers=t;files=f;financial=x;}
 @GetMapping String search(@RequestParam(defaultValue="")@Size(max=80)String q,Model m){m.addAttribute("q",q);m.addAttribute("customers",q.isBlank()?List.of():customers.search(q));return"customers";}
 @GetMapping("/{id}")String view(@PathVariable @Pattern(regexp="C\\d{4}")String id,Model m){m.addAttribute("page",customers.view(id));return"customer-detail";}
 @GetMapping("/{id}/contact")String contact(@PathVariable String id,@RequestParam(defaultValue="")String returnTo,Model m){m.addAttribute("page",customers.view(id));m.addAttribute("returnTo",returnTo);m.addAttribute("form",new ContactForm("",""));return"contact-form";}
 @PostMapping("/{id}/contact")String contactSave(@PathVariable String id,@RequestParam(defaultValue="")String returnTo,@Valid @ModelAttribute("form")ContactForm form,BindingResult errors,Model m){if(errors.hasErrors()){m.addAttribute("page",customers.view(id));m.addAttribute("returnTo",returnTo);return"contact-form";}customers.updateContact(id,form.phone(),form.email());
  return"redirect:"+(returnTo.isBlank()?"/customers/"+id+"?updated":returnTo);}
 @PostMapping("/{id}/cards/{cardId}")String card(@PathVariable String id,@PathVariable String cardId,@RequestParam @Pattern(regexp="temporary_block|permanent_block|unblock|reissue")String action,@RequestParam @Size(min=3,max=160)String reason){var p=customers.view(id).core().customer();auth.require("CARD_MANAGE",p.branch(),p.vulnerable());tiers.transitionCard(auth.user().token(),cardId,action,reason);return"redirect:/customers/"+id+"?cardUpdated";}
 @PostMapping("/{id}/documents")String upload(@PathVariable String id,@RequestParam String category,@RequestHeader(value="X-Case-Branch",required=false)String caseBranch,@RequestParam MultipartFile file)throws IOException{
  files.store(id,caseBranch!=null?caseBranch:customers.view(id).core().customer().branch(),category,file);return"redirect:/customers/"+id+"?uploaded";}
 @PostMapping("/{id}/correspondence")String archive(@PathVariable String id,@RequestParam MultipartFile file)throws IOException{
  var c=customers.view(id).core().customer();files.archive(id,c.branch(),file);return"redirect:/customers/"+id+"?archived";}
 @GetMapping("/{id}/documents/{documentId}")ResponseEntity<org.springframework.core.io.Resource> download(@PathVariable String id,@PathVariable long documentId)throws IOException{var c=customers.view(id).core().customer();var d=files.download(documentId,c.branch());if(!d.metadata().customerId.equals(id))return ResponseEntity.notFound().build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.metadata().contentType)).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+d.metadata().originalName.replace("\"","")+"\"").body(d.resource());}
 @PostMapping("/{id}/financial")String raise(@PathVariable String id,@Valid @ModelAttribute FinancialForm form,BindingResult errors){if(errors.hasErrors())return"redirect:/customers/"+id+"?invalid";var c=customers.view(id).core().customer();financial.raise(form.kind(),id,c.branch(),form.amount(),form.justification(),form.preAuthorized());return"redirect:/customers/"+id+"?requested";}
   @PostMapping("/{id}/financial/drafts")String drafts(@PathVariable String id,@RequestParam @Size(max=8000)String drafts)throws Exception{var c=customers.view(id).core().customer();financial.importDrafts(id,c.branch(),drafts);return"redirect:/customers/"+id+"?requested";}
  @PostMapping("/{id}/telephone-pin")String setPin(@PathVariable String id,@RequestParam @Size(min=4,max=12)String pin){var c=customers.view(id).core().customer();customers.setTelephonePin(id,pin,c.branch());return"redirect:/customers/"+id+"?pinSet";}
  @PostMapping("/{id}/telephone-pin/check")String checkPin(@PathVariable String id,@RequestParam @Size(min=4,max=12)String pin){customers.view(id);return"redirect:/customers/"+id+(customers.verifyTelephonePin(id,pin)?"?pinOk":"?pinBad");}
  public record ContactForm(@NotBlank @Size(max=40)String phone,@Email @Size(max=160)String email){}public record FinancialForm(@Pattern(regexp="FEE_REVERSAL|LIMIT_OVERRIDE")String kind,@DecimalMin("0.01")BigDecimal amount,@NotBlank @Size(max=500)String justification,boolean preAuthorized){}
}
